const { Octokit, App, Action } = require("octokit")
const actionEvent = require('./action-event.js');

const MERGE_LABEL = "✅  Ready for merge"
const CLOSED_LABEL = "🎉 Previously Graduated"

class Octo {
  constructor() {
    this.octokit = new Octokit({ auth: process.env.GH_SECRET });
  }

  async getContent(path) {
    const { data }  = await this.octokit.rest.repos.getContent({
      mediaType: {
        format: "raw",
      },
      owner: actionEvent.pullRepoOwner,
      repo: actionEvent.pullRepo.name,
      path: path,
      ref: actionEvent.pull.head.sha
    });

    return data
  }

  async fetchPr(pr) {
    const { repository: { pullRequest } } = await this.octokit.graphql(
      `
        query myQuery($name: String!, $owner: String!, $pr: Int!){
          repository(name: $name, owner: $owner) {
            pullRequest(number: $pr) {
              author {
                login
              }
              bodyText
              closed
              reviews(first:100) {
                edges{
                  node {
                    body
                    state
                    url
                    author {
                      login
                    }

                    comments(first: 100) {
                      edges {
                        node {
                          body
                          author {
                            login
                          }
                        }
                      }
                    }
                  }
                }
              }

              files(first: 100) {
                edges {
                  node {
                    path
                    additions
                    deletions
                  }
                }
              }
            }
          }
        }
      `,
      {
        name: actionEvent.pullRepo.name,
        owner: actionEvent.pullRepoOwner,
        pr: pr
      }
    )
    return pullRequest
  }

  // comments are an array of objects:

  // path (string) Required. The relative path to the file that necessitates a review comment.
  // position (integer) The position in the diff where you want to add a review comment.
  //          Note this value is not the same as the line number in the file. For help finding
  //          the position value, read the note below.
  // body (string) Required. Text of the review comment.
  // line (integer)
  // side (string)
  // start_line (integer)
  // start_side (string)

  async createReview(content, event="COMMENT", comments=[]) {
    const { data }  = await this.octokit.rest.pulls.createReview({
      accept: "application/vnd.github.v3+json",
      pull_number: actionEvent.pullNumber,
      commit_id: actionEvent.pull.head.sha,
      owner: actionEvent.pullRepoOwner,
      repo: actionEvent.pullRepo.name,
      body: content,
      comments: comments,
      event: event
    });

    return data
  }

  async mergePR() {
    return await this.octokit.request('PUT /repos/{owner}/{repo}/pulls/{pull_number}/merge', {
      owner: actionEvent.pullRepoOwner,
      repo: actionEvent.pullRepo.name,
      pull_number: actionEvent.pullNumber
    });
  }

  async closePR() {
    return await this.octokit.request('PATCH /repos/{owner}/{repo}/pulls/{pull_number}', {
      owner: actionEvent.pullRepoOwner,
      repo: actionEvent.pullRepo.name,
      pull_number: actionEvent.pullNumber,
      state: "closed"
    })
  }

  async addReviewLabel() {
    return await this.addLabel(MERGE_LABEL)
  }

  async addClosedLabel() {
    return await this.addLabel(CLOSED_LABEL)
  }

  async addLabel(label) {
    return await this.octokit.request('POST /repos/{owner}/{repo}/issues/{issue_number}/labels', {
      owner: actionEvent.pullRepoOwner,
      repo: actionEvent.pullRepo.name,
      issue_number: actionEvent.pullNumber,
      labels: [label]
    })
  }
}

module.exports = new Octo()

const Airtable = require('airtable')
const fs = require('fs')

Airtable.configure({
  endpointUrl: 'https://api.airtable.com',
  apiKey: process.env.AIRTABLE_SECRET
});

const GITHUB_GRADUATION = "appQj1OE66mjSGWq8"
const GRADUATES_2020 = "Graduation 2020"
const GRADUATES_2021 = "Graduation 2021"
const GRADUATES_2022 = "Graduation 2022"

let cachedJson
let cachedData = {}

try {
  cachedJson = fs.readFileSync('./app/data/airtable.json', 'utf8')
  cachedData = JSON.parse(cachedJson)
} catch(err) {
  console.log("Failed to parse cache", err)
}


class ATable {
  constructor() {

  }

  userParticipatedPrior(githubLogin, year) {
    const data = this.fetchFromCache(githubLogin, year)

    if(data) {
      console.log("found cached " + year + " data")
      return Promise.resolve(data)
    }

    return this.fetchGraduate(githubLogin, year)
  }

  async fetchGraduate(githubLogin, year) {
    const data = this.fetchFromCache(githubLogin, year)
    if(data[0] || data[1]) {
      console.log("found cached 2021 or 2020 data")
      return Promise.resolve(data)
    }

    return this.fetchGraduate(githubLogin, GRADUATES_2021)
  }

  async fetchAll(table) {
    const airtable = Airtable.base(GITHUB_GRADUATION);
    const users = {}

    return new Promise((resolve, reject)=>{
      airtable(table).select().eachPage(function page(records, fetchNextPage) {
        // This function (`page`) will get called for each page of records.

        records.forEach(function(record) {
          users[record.fields["GitHub Username"]] = record.fields
        });

        // To fetch the next page of records, call `fetchNextPage`.
        // If there are more records, `page` will get called again.
        // If there are no more records, `done` will get called.
        fetchNextPage();

      }, function done(err) {
          if (err) {
            console.error(err);
            reject(err)
          }
          resolve(users)
      });
    })
  }

  async fetchAll2022() {
    return await this.fetchAll(GRADUATES_2022)
  }

  async fetchAll2021() {
    return await this.fetchAll(GRADUATES_2021)
  }

  async fetchAll2020() {
    return await this.fetchAll(GRADUATES_2020)
  }

  fetchFromCache(githubLogin, table) {
    let data

    if(table === GRADUATES_2020) {
      data = cachedData["grad2020"]
    } else if(table === GRADUATES_2021) {
      data = cachedData["grad2021"]
    } else if(table === GRADUATES_2022) {
      data = cachedData["grad2022"]
    }

    if(data) {
      return data[githubLogin]
    }
  }

  fetchGraduate(githubLogin, table) {
    const airtable = Airtable.base(GITHUB_GRADUATION);
    const data = []
    return new Promise((resolve, reject)=>{
      airtable(table).select({
        // Selecting the first 3 records in Pending Reviews:
        maxRecords: 1,
        filterByFormula: `{GitHub Username} = '${githubLogin}'`
        // view: "Pending Reviews",
        // filterByFormula: `{GitHub Username} = '${}'`
      }).eachPage(function page(records, fetchNextPage) {
        // This function (`page`) will get called for each page of records.
        records.forEach(function(record) {
          data.push(record.fields)
        });

        fetchNextPage()
      }, function done(err) {
        if (err) {
          if(err.error === "NOT_FOUND") {
            resolve(false)
          }

          reject(err)
          return;
        }

        resolve(data[0])
      });

    }).catch((err)=>{
      reject(err)
    })
  }
}

module.exports = new ATable()

